) as v(codigo_ibge, municipio, uf, regional, coord);

do $$
declare v_org uuid; v_faltam text;
begin
  select id into v_org from public.organizations where name = 'Marcher Brasil' limit 1;
  if v_org is null then raise exception '260: organizacao Marcher Brasil nao encontrada'; end if;
  select string_agg(distinct s.regional, ', ' order by s.regional) into v_faltam
  from _seed_municipios s
  where not exists (select 1 from public.comercial_territorios t where t.organization_id = v_org and t.nome = s.regional);
  if v_faltam is not null then
    raise exception '260: cadastre em Parametros > Comercial > Territorio antes de rodar: %', v_faltam;
  end if;
end $$;

insert into public.comercial_regioes_municipio (organization_id, codigo_ibge, municipio, uf, territorio_id, coord)
select t.organization_id, s.codigo_ibge, s.municipio, s.uf, t.id, s.coord
from _seed_municipios s
join public.organizations o on o.name = 'Marcher Brasil'
join public.comercial_territorios t on t.organization_id = o.id and t.nome = s.regional
on conflict (organization_id, codigo_ibge) do update
  set municipio = excluded.municipio, uf = excluded.uf, territorio_id = excluded.territorio_id, coord = excluded.coord, updated_at = now();

commit;
